import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.DBosx3SP.js";const h=JSON.parse('{"title":"Animation","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/animation.md","filePath":"rendering/animation.md","lastUpdated":1792996843000}'),o={name:"rendering/animation.md"};function r(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="animation" tabindex="-1">Animation <a class="header-anchor" href="#animation" aria-label="Permalink to &quot;Animation&quot;">​</a></h1><h2 id="_1-zoom-pan" tabindex="-1">1. Zoom / Pan <a class="header-anchor" href="#_1-zoom-pan" aria-label="Permalink to &quot;1. Zoom / Pan&quot;">​</a></h2><p>This only requires updating an uniform variable. There is no wgpu::Buffer update.</p><p>The most expensive update is to <strong>update ticks</strong> and <strong>find new nice numbers</strong>.</p><p>Challenge: Ease-out should happen in transformed or pixel space, not data space (e.g. log scale)<br> TODO: The touch interaction requires a spring physics to simulate the speed and acceleration.</p><h2 id="_2-start-animation" tabindex="-1">2. Start Animation <a class="header-anchor" href="#_2-start-animation" aria-label="Permalink to &quot;2. Start Animation&quot;">​</a></h2><p>A data update from initial state (None) will auto-trigger the startup animation.</p><p>Example ideas:</p><ul><li>bar: starts from baseline</li><li>band: progressive reveal</li><li>marker: combine position, size, alpha in 800ms-1s</li><li>A line size starts from 0</li><li>An alpha starts from 0</li></ul><h2 id="_3-data-update" tabindex="-1">3. Data Update <a class="header-anchor" href="#_3-data-update" aria-label="Permalink to &quot;3. Data Update&quot;">​</a></h2><ul><li>per-vertex: (old: f32) to (new: f32), from (start_t: f32) to (end_t: f32)</li><li>uniform: (current_t: f32)</li></ul><h2 id="_4-touch-screen-zoom-pan-todo" tabindex="-1">4. Touch Screen Zoom / Pan (TODO) <a class="header-anchor" href="#_4-touch-screen-zoom-pan-todo" aria-label="Permalink to &quot;4. Touch Screen Zoom / Pan (TODO)&quot;">​</a></h2><p>The mouse scroll only needs easing-out but touch interaction (pinch zoom, elastic scroll) requires spring physics to simulate the velocity and acceleration.</p><p>Velocity is preserved when starting new animation during another animation.</p><p>Easing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Zoom 1:    ●━━━━━━━━━━━━━━━━━━●</span></span>
<span class="line"><span>                      ↑ interrupted</span></span>
<span class="line"><span>  Zoom 2:             ●━━━━━━━━━━━━━━●</span></span>
<span class="line"><span>                      └── abrupt restart, no momentum</span></span></code></pre></div><p>Spring:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Zoom 1:    ●━━━━━━━╮</span></span>
<span class="line"><span>                     ╰━━━━━━━●  ← smoothly curves toward new target</span></span>
<span class="line"><span>                     ↑ target changed, velocity preserved</span></span></code></pre></div><hr><h2 id="ai-survey-transition" tabindex="-1">AI Survey: transition <a class="header-anchor" href="#ai-survey-transition" aria-label="Permalink to &quot;AI Survey: transition&quot;">​</a></h2><h3 id="heer-robertson-2007-—-animated-transitions-in-statistical-data-graphics" tabindex="-1">Heer &amp; Robertson (2007) — Animated Transitions in Statistical Data Graphics <a class="header-anchor" href="#heer-robertson-2007-—-animated-transitions-in-statistical-data-graphics" aria-label="Permalink to &quot;Heer &amp; Robertson (2007) — Animated Transitions in Statistical Data Graphics&quot;">​</a></h3><blockquote><p>IEEE Transactions on Visualization and Computer Graphics (Proc. InfoVis), 13(6), 1240–1247</p></blockquote><p>The foundational study on animated transitions between statistical data graphics (bar charts, pie charts, scatter plots). Two controlled experiments found:</p><ul><li><strong>Animated transitions significantly improved graphical perception</strong> over static transitions at both the syntactic (object tracking) and semantic (change estimation) levels of analysis.</li><li><strong>Simple transitions (~1 second, e.g. translation) outperformed complex ones</strong> (e.g. rotation).</li><li><strong>Staged animation</strong> — breaking a complex transition into sequential simpler steps — was <strong>preferred</strong> over simultaneous animation, which was preferred over no animation at all.</li><li>For <strong>scatter plots</strong> specifically, no significant accuracy difference was found between staged and simultaneous animation.</li></ul><p><a href="https://idl.uw.edu/papers/animated-transitions" target="_blank" rel="noreferrer">Paper</a> ·<br><a href="https://idl.cs.washington.edu/files/2007-AnimatedTransitions-InfoVis.pdf" target="_blank" rel="noreferrer">PDF</a></p><hr><h3 id="chevalier-dragicevic-franconeri-2014-—-the-not-so-staggering-effect-of-staggered-animations-on-visual-tracking" tabindex="-1">Chevalier, Dragicevic &amp; Franconeri (2014) — The Not-so-Staggering Effect of Staggered Animations on Visual Tracking <a class="header-anchor" href="#chevalier-dragicevic-franconeri-2014-—-the-not-so-staggering-effect-of-staggered-animations-on-visual-tracking" aria-label="Permalink to &quot;Chevalier, Dragicevic &amp; Franconeri (2014) — The Not-so-Staggering Effect of Staggered Animations on Visual Tracking&quot;">​</a></h3><blockquote><p>IEEE Transactions on Visualization and Computer Graphics, 2014</p></blockquote><p>Examines whether staggering (incremental delay in element start times) improves tracking performance:</p><ul><li>Staggering had a <strong>negligible or even negative</strong> impact on multiple object tracking performance.</li><li>Despite the intuition that staggering reduces visual overload and occlusion, <strong>empirical evidence did not support this</strong>.</li><li>The effect held across different dot-cloud / scatter-plot-like scenarios.</li></ul><p><a href="https://www.researchgate.net/publication/273396391_The_Not-so-Staggering_Effect_of_Staggered_Animations_on_Visual_Tracking" target="_blank" rel="noreferrer">Paper</a> ·<br><a href="https://inria.hal.science/hal-01054408v1" target="_blank" rel="noreferrer">HAL</a></p><hr><h3 id="kim-heer-2021-—-gemini-a-grammar-and-recommender-system-for-animated-transitions" tabindex="-1">Kim &amp; Heer (2021) — Gemini: A Grammar and Recommender System for Animated Transitions <a class="header-anchor" href="#kim-heer-2021-—-gemini-a-grammar-and-recommender-system-for-animated-transitions" aria-label="Permalink to &quot;Kim &amp; Heer (2021) — Gemini: A Grammar and Recommender System for Animated Transitions&quot;">​</a></h3><blockquote><p>IEEE Transactions on Visualization and Computer Graphics, 2021</p></blockquote><p>Formalizes animated transitions into a declarative grammar decomposing them into <strong>enter, exit, update</strong> steps for marks, axes, and legends. The cost function for ranking animation designs was informed by perceptual studies and prefers:</p><ul><li>Transitions that maintain <strong>object constancy</strong> (a mark representing the same data point is visually trackable through the animation).</li><li><strong>Staged</strong> over simultaneous transitions when multiple visual properties change.</li></ul><p><a href="https://idl.uw.edu/papers/gemini" target="_blank" rel="noreferrer">Paper</a> ·<br><a href="https://arxiv.org/abs/2009.01429" target="_blank" rel="noreferrer">arXiv</a></p><hr><h3 id="huth-blascheck-koch-ertl-2023-—-studies-and-design-considerations-for-animated-transitions-between-small-scale-visualizations" tabindex="-1">Huth, Blascheck, Koch &amp; Ertl (2023) — Studies and Design Considerations for Animated Transitions Between Small-Scale Visualizations <a class="header-anchor" href="#huth-blascheck-koch-ertl-2023-—-studies-and-design-considerations-for-animated-transitions-between-small-scale-visualizations" aria-label="Permalink to &quot;Huth, Blascheck, Koch &amp; Ertl (2023) — Studies and Design Considerations for Animated Transitions Between Small-Scale Visualizations&quot;">​</a></h3><blockquote><p>Journal of Visualization, August 2023</p></blockquote><p>Two online studies on animated transitions in small-scale contexts (mobile, embedded in text, geographical overlays):</p><ul><li>Animated transitions are understandable at small scale, but effectiveness <strong>depends heavily on the specific task and operation type</strong>.</li><li>Design considerations differ from normal-sized visualizations.</li></ul><p><a href="https://link.springer.com/article/10.1007/s12650-023-00937-z" target="_blank" rel="noreferrer">Paper</a></p><hr><h3 id="robertson-et-al-—-animation-for-visualization-book-chapter" tabindex="-1">Robertson et al. — Animation for Visualization (Book Chapter) <a class="header-anchor" href="#robertson-et-al-—-animation-for-visualization-book-chapter" aria-label="Permalink to &quot;Robertson et al. — Animation for Visualization (Book Chapter)&quot;">​</a></h3><blockquote><p>Microsoft Research, Chapter 19 in <em>Beautiful Visualization</em></p></blockquote><p>Provides design principles for visualization animation:</p><ul><li><strong>Maximize predictability</strong> — if the viewer can predict where an element is going after seeing a fraction of the trajectory, cognitive load drops.</li><li><strong>Slow-in, slow-out easing</strong> feels natural and aids tracking.</li><li><strong>Gestalt common fate</strong> — elements that move together are perceived as related (grouped).</li></ul><p><a href="https://www.microsoft.com/en-us/research/wp-content/uploads/2016/02/bv_ch19.pdf" target="_blank" rel="noreferrer">PDF</a></p><hr><h2 id="ai-survey-ease-function" tabindex="-1">AI Survey: ease function <a class="header-anchor" href="#ai-survey-ease-function" aria-label="Permalink to &quot;AI Survey: ease function&quot;">​</a></h2><p>No study directly compares fade-in vs. grow vs. fly-in as entrance animations in a controlled experiment. However, the principles above provide strong guidance.</p><h3 id="comparison-of-techniques" tabindex="-1">Comparison of Techniques <a class="header-anchor" href="#comparison-of-techniques" aria-label="Permalink to &quot;Comparison of Techniques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Technique</th><th>Description</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td><strong>Alpha (fade in)</strong></td><td>Opacity interpolates from 0 to 1</td><td>Low cognitive load; does not imply spatial meaning; bubble size is immediately visible and accurate</td><td>No object constancy benefit — element &quot;appears&quot; rather than &quot;arrives&quot;</td></tr><tr><td><strong>Position (fly from center)</strong></td><td>Bubble moves from a shared origin to its destination</td><td>Leverages object constancy; viewers can track trajectory; communicates spatial placement</td><td>Can cause crowding/occlusion when many bubbles move simultaneously; staggering does not reliably help (Chevalier et al. 2014)</td></tr><tr><td><strong>Size (grow)</strong></td><td>Radius interpolates from 0 to final value</td><td>Naturally draws attention to the size-encoded variable; smooth, focused reveal</td><td>May mislead viewers into thinking size <em>changed</em> rather than was <em>introduced</em>; briefly misrepresents the data value</td></tr></tbody></table><h3 id="recommendations-from-the-literature" tabindex="-1">Recommendations from the Literature <a class="header-anchor" href="#recommendations-from-the-literature" aria-label="Permalink to &quot;Recommendations from the Literature&quot;">​</a></h3><ol><li><p><strong>Combine properties.</strong> The research (Heer &amp; Robertson 2007; Kim &amp; Heer 2021) suggests interpolating position, size, and opacity simultaneously over a short duration (~800ms–1s) with ease-in-out timing. This is essentially what D3&#39;s <code>enter()</code> transitions and Gemini&#39;s grammar recommend — bringing elements in with all their visual properties at once to maintain object constancy and avoid implying non-existent data changes.</p></li><li><p><strong>Keep it short and simple.</strong> Transitions around 1 second with simple motion (translation) outperformed longer or more complex ones.</p></li><li><p><strong>Avoid staggering for tracking tasks.</strong> If the goal is for viewers to track individual bubbles, staggering start times does not help and may hurt performance.</p></li><li><p><strong>Use easing.</strong> Slow-in, slow-out (ease-in-out) timing feels natural and aids visual tracking.</p></li><li><p><strong>If choosing a single technique:</strong></p><ul><li><strong>Position from center</strong> is most aligned with the object constancy principle.</li><li><strong>Alpha fade</strong> is the safest choice that will not accidentally mislead about the data.</li><li><strong>Size grow</strong> is the riskiest — it temporarily shows incorrect data values during the animation.</li></ul></li></ol>`,56)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
